'use strict';

// Application Configuration
const CONFIG = {
  currency: 'â‚¦',
  whatsappNumber: '2347031696283',
  paystackUrl: 'https://paystack.com/pay/',
  storageKey: 'topHairCart',
  notificationDuration: 3000
};

// Cart Management
class CartManager {
  constructor() {
    this.cart = [];
    this.loadFromStorage();
  }

  loadFromStorage() {
    try {
      const saved = localStorage.getItem(CONFIG.storageKey);
      if (saved) {
        this.cart = JSON.parse(saved);
      }
    } catch (error) {
      console.error('Error loading cart:', error);
      this.cart = [];
    }
  }

  saveToStorage() {
    try {
      localStorage.setItem(CONFIG.storageKey, JSON.stringify(this.cart));
    } catch (error) {
      console.error('Error saving cart:', error);
    }
  }

  addItem(name, price, quantity = 1) {
    if (!name || !price || price <= 0 || quantity <= 0) {
      showNotification('Invalid product details', 'error');
      return false;
    }

    const existing = this.cart.find(item => item.name === name);
    
    if (existing) {
      existing.quantity += quantity;
      existing.totalPrice = existing.quantity * existing.unitPrice;
    } else {
      this.cart.push({
        id: Date.now(),
        name: name,
        unitPrice: price,
        quantity: quantity,
        totalPrice: price * quantity
      });
    }

    this.saveToStorage();
    this.display();
    showNotification(`${name} added to cart!`, 'success');
    return true;
  }

  removeItem(id) {
    const index = this.cart.findIndex(item => item.id === id);
    
    if (index !== -1) {
      const itemName = this.cart[index].name;
      this.cart.splice(index, 1);
      this.saveToStorage();
      this.display();
      showNotification(`${itemName} removed from cart`, 'info');
      return true;
    }
    return false;
  }

  getTotal() {
    return this.cart.reduce((sum, item) => sum + item.totalPrice, 0);
  }

  getItemCount() {
    return this.cart.reduce((sum, item) => sum + item.quantity, 0);
  }

  clear() {
    this.cart = [];
    this.saveToStorage();
    this.display();
  }

  display() {
    const cartEl = document.getElementById('cartItems');
    const totalEl = document.getElementById('total');
    
    if (!cartEl || !totalEl) return;

    if (this.cart.length === 0) {
      cartEl.innerHTML = '<p class="empty-cart">Your cart is empty</p>';
      totalEl.textContent = CONFIG.currency + '0';
      return;
    }

    let html = '';
    this.cart.forEach(item => {
      html += `
        <div class="cart-item">
          <div class="cart-item-details">
            <strong class="cart-item-name">${escapeHtml(item.name)}</strong>
            <small class="cart-item-price">${CONFIG.currency}${item.unitPrice.toLocaleString()} Ã— ${item.quantity}</small>
          </div>
          <div class="cart-item-actions">
            <strong class="cart-item-total">${CONFIG.currency}${item.totalPrice.toLocaleString()}</strong>
            <button onclick="cartManager.removeItem(${item.id})" class="btn-remove" aria-label="Remove ${escapeHtml(item.name)}">
              Remove
            </button>
          </div>
        </div>
      `;
    });

    cartEl.innerHTML = html;
    totalEl.textContent = CONFIG.currency + this.getTotal().toLocaleString();
  }
}

// Initialize cart manager
const cartManager = new CartManager();

// Global functions for backward compatibility
function addToCart(name, price, quantity = 1) {
  return cartManager.addItem(name, price, quantity);
}

function removeFromCart(id) {
  return cartManager.removeItem(id);
}

function displayCart() {
  cartManager.display();
}

// Checkout Functions
function checkout() {
  if (cartManager.cart.length === 0) {
    showNotification('Your cart is empty!', 'error');
    return;
  }

  const total = cartManager.getTotal();
  const count = cartManager.getItemCount();
  
  const message = `Thank you for your order!\n\nItems: ${count}\nTotal: ${CONFIG.currency}${total.toLocaleString()}\n\nYou will be redirected to complete your order.`;
  
  if (confirm(message)) {
    // Redirect to WhatsApp with order details
    const orderDetails = cartManager.cart.map(item => 
      `${item.name} (${item.quantity}x) - ${CONFIG.currency}${item.totalPrice.toLocaleString()}`
    ).join('%0A');
    
    const whatsappMessage = `Hello! I want to place an order:%0A%0A${orderDetails}%0A%0ATotal: ${CONFIG.currency}${total.toLocaleString()}`;
    window.location.href = `https://wa.me/${CONFIG.whatsappNumber}?text=${whatsappMessage}`;
  }
}

function payOnline() {
  if (cartManager.cart.length === 0) {
    showNotification('Your cart is empty!', 'error');
    return;
  }

  const total = cartManager.getTotal();
  
  if (confirm(`Proceed to pay ${CONFIG.currency}${total.toLocaleString()} online?`)) {
    // In production, integrate with actual Paystack API
    window.open(CONFIG.paystackUrl, '_blank');
  }
}

